namespace Frociart {
    internal sealed class CodeTemplateLibrary : Form {
        internal readonly TextBox Search=Ui.TextBox();internal readonly ListBox Results=new ListBox();internal readonly CheckBox Trash=new CheckBox{Text="Cestino",AutoSize=true};
        internal readonly Label Details=Ui.Label("",10,Ui.Ink),Status=Ui.Label("",9.5f,Ui.Muted);
        internal readonly FlowButton NewButton,ImportButton,EditButton,DuplicateButton,ExportButton,ArchiveButton,DeleteButton,UseButton,CloseButton;
        internal Func<string> ImportPathPicker;internal Func<string,string> ExportPathPicker;internal FlowSourceTarget SelectedTarget;internal Exception LastError;
        readonly FlowTemplateStore store;readonly Diagram document;readonly List<FlowTemplateStore.Entry> entries=new List<FlowTemplateStore.Entry>();IList<FlowTemplateStore.Entry> all=new List<FlowTemplateStore.Entry>();Task<Exception> pending=Task.FromResult<Exception>(null);int loadEpoch;bool busy;string selectedId;
        internal CodeTemplateLibrary(FlowTemplateStore store,Diagram document){this.store=store;this.document=DiagramIO.Clone(document);Text="Modelli di codice — Frociart";StartPosition=FormStartPosition.CenterParent;Size=new Size(900,720);MinimumSize=new Size(700,560);ShowInTaskbar=false;MinimizeBox=false;AutoScaleDimensions=new SizeF(96,96);AutoScaleMode=AutoScaleMode.Dpi;Font=Ui.Font();BackColor=Ui.Surface;
            var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),ColumnCount=1,RowCount=6};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(var row in new[]{new RowStyle(SizeType.Absolute,52),new RowStyle(SizeType.Absolute,43),new RowStyle(SizeType.Percent,100),new RowStyle(SizeType.Absolute,110),new RowStyle(SizeType.Absolute,42),new RowStyle(SizeType.Absolute,88)})layout.RowStyles.Add(row);Controls.Add(layout);
            var intro=Ui.Label("Il codice, nel formato che preferisci\nParti da un generatore oppure crea un formato tuo.",12,Ui.Ink,true);intro.Dock=DockStyle.Fill;layout.Controls.Add(intro,0,0);
            var tools=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,Margin=Padding.Empty};tools.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,114));tools.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,112));tools.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));tools.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));NewButton=Ui.Button("Nuovo",105,New);ImportButton=Ui.Button("Importa…",105,Import);tools.Controls.Add(NewButton,0,0);tools.Controls.Add(ImportButton,1,0);Search.Dock=DockStyle.Fill;Search.MaxLength=100;Search.AccessibleName="Cerca nei modelli di codice";tools.Controls.Add(Search,2,0);Trash.Dock=DockStyle.Fill;Trash.AccessibleName="Mostra il cestino dei modelli";tools.Controls.Add(Trash,3,0);layout.Controls.Add(tools,0,1);
            Results.Dock=DockStyle.Fill;Results.IntegralHeight=false;Results.BorderStyle=BorderStyle.None;Results.Font=Ui.Font(11);Results.AccessibleName="Modelli di codice disponibili";Results.DrawMode=DrawMode.OwnerDrawFixed;Results.ItemHeight=40;Results.DrawItem+=DrawItem;Results.SelectedIndexChanged+=delegate{Describe();};Results.DoubleClick+=delegate{if(UseButton.Enabled)Choose();};layout.Controls.Add(Results,0,2);
            Details.Dock=DockStyle.Fill;Details.Padding=new Padding(0,10,0,0);layout.Controls.Add(Details,0,3);Status.Dock=DockStyle.Fill;Status.AutoEllipsis=true;layout.Controls.Add(Status,0,4);
            var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,Margin=Padding.Empty};UseButton=Ui.Button("Usa modello",135,Choose,true);EditButton=Ui.Button("Modifica",95,Edit);DuplicateButton=Ui.Button("Duplica",90,Duplicate);ExportButton=Ui.Button("Esporta…",95,Export);ArchiveButton=Ui.Button("Nel cestino",112,ArchiveOrRestore);DeleteButton=Ui.Button("Elimina",90,Delete);CloseButton=Ui.Button("Chiudi",90,Close);foreach(var button in new[]{UseButton,EditButton,DuplicateButton,ExportButton,ArchiveButton,DeleteButton,Ui.Button("Guida",75,()=>CodeTemplateUi.ShowGuide(this)),CloseButton})footer.Controls.Add(button);layout.Controls.Add(footer,0,5);CancelButton=CloseButton;
            Search.TextChanged+=delegate{Filter();};Trash.CheckedChanged+=delegate{Reload();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy)e.Cancel=true;};Ui.ApplyTheme(this);Describe();Shown+=delegate{using(var graphics=CreateGraphics())Results.ItemHeight=(int)Math.Round(40*graphics.DpiX/96f);Search.Focus();Reload();};
        }
        internal FlowTemplateStore.Entry Current {get{return Results.SelectedIndex<0||Results.SelectedIndex>=entries.Count?null:entries[Results.SelectedIndex];}}
        void DrawItem(object sender,DrawItemEventArgs e){if(e.Index<0||e.Index>=entries.Count)return;var entry=entries[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(selected?Ui.Hover:Ui.Paper))e.Graphics.FillRectangle(brush,e.Bounds);string name=entry.Name;string tag=entry.Problem!=null?"Da recuperare":entry.Draft!=null?"Bozza presente":entry.Definition==null?"Da completare":FlowSourceTarget.NameOf(entry.Definition.Base);var bounds=e.Bounds;int pad=(int)Math.Round(10*e.Graphics.DpiX/96f),right=(int)Math.Round(140*e.Graphics.DpiX/96f);TextRenderer.DrawText(e.Graphics,name,Results.Font,new Rectangle(bounds.X+pad,bounds.Y,Math.Max(1,bounds.Width-right-pad*2),bounds.Height),selected?Ui.Blue:Ui.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);using(var small=Ui.Font(9))TextRenderer.DrawText(e.Graphics,tag,small,new Rectangle(bounds.Right-right-pad,bounds.Y,right,bounds.Height),Ui.Muted,TextFormatFlags.Right|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();}
        void SetStatus(string value,bool error=false){Status.Text=value;Status.AccessibleDescription=value;Status.ForeColor=error?Ui.Amber:Ui.Muted;}
        void Queue(Action work,Action done){var job=pending.ContinueWith(previous=>{try{work();return null;}catch(Exception error){return error;}},TaskScheduler.Default);pending=job;job.ContinueWith(completed=>{if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke(new Action(delegate{if(IsDisposed)return;if(completed.Result!=null){LastError=completed.Result;Busy(false);SetStatus(completed.Result.Message,true);}else done();}));}catch(InvalidOperationException){/* Closing the window does not cancel completed file work. */}});}
        void Busy(bool value){busy=value;Search.Enabled=Trash.Enabled=Results.Enabled=NewButton.Enabled=ImportButton.Enabled=CloseButton.Enabled=!value;Describe();}
        internal void Reload(string select=null){if(select!=null)selectedId=select;int ticket=++loadEpoch;bool archived=Trash.Checked;Busy(true);SetStatus("Leggo i modelli…");IList<FlowTemplateStore.Entry> loaded=null;Queue(()=>loaded=store.Entries(archived),()=>{if(ticket!=loadEpoch)return;all=loaded;Busy(false);Filter();SetStatus(all.Count==0?archived?"Il cestino è vuoto.":"Nessun modello personale. Crea un modello oppure importa un file .frotemplate o .fpgt.":archived?"Ripristina un modello oppure eliminalo definitivamente.":"Usa modello apre il testo generato dalla versione salvata.");});}
        void Filter(){string query=Search.Text.Trim();Results.BeginUpdate();entries.Clear();Results.Items.Clear();foreach(var entry in all)if((entry.Name+" "+(entry.Definition==null?"":entry.Definition.Base)).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0){entries.Add(entry);Results.Items.Add(entry.Name);}int chosen=entries.FindIndex(e=>e.Id==selectedId);if(entries.Count>0)Results.SelectedIndex=chosen>=0?chosen:0;Results.EndUpdate();Describe();}
        void Describe(){var entry=Current;if(entry!=null)selectedId=entry.Id;bool active=entry!=null&&!Trash.Checked&&!busy;UseButton.Enabled=active&&entry.Definition!=null;EditButton.Enabled=active&&(entry.Definition!=null||entry.Draft!=null);DuplicateButton.Enabled=active&&entry.Definition!=null;ExportButton.Enabled=entry!=null&&!busy&&(entry.Definition!=null||entry.Raw!=null||entry.Draft!=null);ArchiveButton.Enabled=entry!=null&&!busy;ArchiveButton.Text=Trash.Checked?"Ripristina":"Nel cestino";DeleteButton.Visible=Trash.Checked;DeleteButton.Enabled=entry!=null&&Trash.Checked&&!busy;if(entry==null){Details.Text="Scegli un modello dall’elenco.";return;}Details.Text=entry.Name+"\n"+(entry.Definition==null?"Modello da completare o recuperare.":FlowSourceTarget.NameOf(entry.Definition.Base)+" · ."+entry.Definition.Extension)+(entry.Draft==null?"":"\nBozza presente. Usa modello utilizza la versione salvata; Modifica recupera la bozza.")+(entry.Problem==null?"":"\n"+entry.Problem);Details.AccessibleDescription=Details.Text;}
        string UniqueName(string name){name=name.Trim();var used=store.Entries().Where(e=>e.Definition!=null).Select(e=>e.Definition.Name).ToList();if(!used.Contains(name,StringComparer.OrdinalIgnoreCase))return name;for(int i=2;i<1000;i++){string suffix=" ("+i+")";string start=name.Substring(0,Math.Min(name.Length,80-suffix.Length));if(start.Length>0&&Char.IsHighSurrogate(start[start.Length-1]))start=start.Substring(0,start.Length-1);string candidate=start+suffix;if(!used.Contains(candidate,StringComparer.OrdinalIgnoreCase))return candidate;}throw new IOException("Scegli un nome diverso per il modello.");}
        void OpenEditor(string id,FlowTemplateDraft initial){try{using(var editor=new CodeTemplateEditor(store,id,initial,document)){editor.ShowDialog(this);Reload(id);if(editor.Warning!=null)SetStatus(editor.Warning,true);}}catch(Exception error){if(!(error is IOException)&&!(error is UnauthorizedAccessException)&&!(error is ArgumentException))throw;SetStatus(CodeTemplateUi.Problem(error),true);}}
        internal void New(){if(busy)return;try{OpenEditor(FlowTemplateStore.NewId(),new FlowTemplateDraft(UniqueName("Il mio modello"),"python","py",FlowSourceTarget.Python.Instructions,"{{ source }}"));}catch(IOException error){SetStatus(CodeTemplateUi.Problem(error),true);}}
        internal void Edit(){var entry=Current;if(busy||entry==null||Trash.Checked)return;try{if(entry.Draft!=null)FlowTemplateDraft.Decode(entry.Draft);if(entry.Definition==null&&entry.Raw!=null){if(entry.Draft==null){SetStatus("Il modello salvato non è leggibile. Esporta una copia per recuperarlo.",true);return;}var copy=FlowTemplateDraft.Decode(entry.Draft);OpenEditor(FlowTemplateStore.NewId(),new FlowTemplateDraft(UniqueName(copy.Name.Length==0?"Modello recuperato":copy.Name),copy.Base,copy.Extension,copy.Instructions,copy.Body,copy.CaseSensitive));return;}OpenEditor(entry.Id,null);}catch(ArgumentException){RecoverDraft(entry);}}
        internal void Duplicate(){var entry=Current;if(busy||entry==null||entry.Definition==null||Trash.Checked)return;try{var d=entry.Definition;OpenEditor(FlowTemplateStore.NewId(),new FlowTemplateDraft(UniqueName(d.Name),d.Base,d.Extension,d.Instructions,d.Body,d.CaseSensitive));}catch(IOException error){SetStatus(CodeTemplateUi.Problem(error),true);}}
        internal void Import(){if(busy)return;string path=null;if(ImportPathPicker!=null)path=ImportPathPicker();else using(var picker=new OpenFileDialog{Title="Importa un modello di codice",Filter="Modelli di codice (*.frotemplate;*.fpgt)|*.frotemplate;*.fpgt|Tutti i file (*.*)|*.*",RestoreDirectory=true})if(picker.ShowDialog(this)==DialogResult.OK)path=picker.FileName;if(path!=null)ImportFromPath(path);}
        internal void ImportFromPath(string path){if(busy)return;Busy(true);SetStatus("Leggo il modello…");FlowCodeTemplate definition=null;Queue(()=>definition=FlowCodeTemplate.Parse(FlowTemplateStore.ReadImport(path)),()=>{Busy(false);try{OpenEditor(FlowTemplateStore.NewId(),new FlowTemplateDraft(UniqueName(definition.Name),definition.Base,definition.Extension,definition.Instructions,definition.Body,definition.CaseSensitive));}catch(IOException error){SetStatus(CodeTemplateUi.Problem(error),true);}});}
        string PickExport(string name){if(ExportPathPicker!=null)return ExportPathPicker(name);using(var picker=new SaveFileDialog{Title="Esporta il modello",Filter="Modelli di codice (*.frotemplate;*.fpgt)|*.frotemplate;*.fpgt|Testo (*.txt)|*.txt",DefaultExt=Path.GetExtension(name).TrimStart('.'),AddExtension=true,FileName=name,OverwritePrompt=true,RestoreDirectory=true})return picker.ShowDialog(this)==DialogResult.OK?picker.FileName:null;}
        internal void Export(){var entry=Current;if(busy||entry==null)return;string path=PickExport(entry.Definition==null?"Modello_da_recuperare.txt":"Modello."+entry.Definition.FileExtension);if(path!=null)ExportSelected(path);}
        internal void ExportSelected(string path){var entry=Current;if(entry==null||busy)return;Busy(true);SetStatus("Esporto il modello…");Queue(()=>{if(entry.Definition!=null)FlowTemplateStore.Export(path,entry.Definition);else SourceCodeDialog.WriteSource(path,entry.Raw??entry.Draft);},()=>{Busy(false);SetStatus("Copia esportata: "+Path.GetFileName(path));});}
        internal void ArchiveOrRestore(){var entry=Current;if(busy||entry==null)return;bool restore=Trash.Checked;Busy(true);SetStatus(restore?"Ripristino il modello…":"Sposto il modello nel cestino…");Queue(()=>{if(restore)store.Restore(entry.Id);else store.Archive(entry.Id,entry.Fingerprint);},()=>Reload());}
        internal void Delete(){var entry=Current;if(busy||entry==null||!Trash.Checked)return;if(FlowMessageDialog.Show(this,"Eliminare definitivamente questo modello e la sua bozza? Non sarà possibile ripristinarli.","Elimina modello",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;Busy(true);SetStatus("Elimino il modello dal cestino…");Queue(()=>store.DeleteArchived(entry.Id),()=>Reload());}
        internal void Choose(){var entry=Current;if(busy||entry==null||entry.Definition==null||Trash.Checked)return;SelectedTarget=FlowSourceTarget.FromTemplate(entry.Id,entry.Definition);DialogResult=DialogResult.OK;Close();}
        void RecoverDraft(FlowTemplateStore.Entry entry){if(entry.Draft==null){SetStatus("Non riesco a leggere la bozza. I file originali sono conservati.",true);return;}using(var dialog=new Form{Text="Bozza da recuperare — Frociart",Size=new Size(760,600),MinimumSize=new Size(600,420),StartPosition=FormStartPosition.CenterParent,BackColor=Ui.Surface,Padding=new Padding(20),ShowInTaskbar=false,Font=Ui.Font()}){var text=Ui.TextBox(true);text.ReadOnly=true;text.Dock=DockStyle.Fill;text.ScrollBars=ScrollBars.Both;text.MaxLength=FlowTemplateStore.MaxDraftCharacters;text.Text=entry.Draft;text.AccessibleName="Contenuto della bozza da recuperare";dialog.Controls.Add(text);var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=44};actions.Controls.Add(Ui.Button("Esporta copia",135,delegate{string path=PickExport("Bozza_modello.txt");if(path==null)return;try{SourceCodeDialog.WriteSource(path,entry.Draft);SetStatus("Copia della bozza esportata.");}catch(IOException error){SetStatus(CodeTemplateUi.Problem(error),true);}}));actions.Controls.Add(Ui.Button("Scarta bozza",125,delegate{if(FlowMessageDialog.Show(dialog,"Scartare questa bozza? Il modello salvato resta invariato.","Scarta bozza",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;try{if(!store.ClearDraft(entry.Id,entry.Draft))throw new IOException("La bozza è cambiata. Riapri il modello.");dialog.Close();Reload(entry.Id);}catch(IOException error){SetStatus(CodeTemplateUi.Problem(error),true);}}));var close=Ui.Button("Chiudi",90,dialog.Close);actions.Controls.Add(close);dialog.Controls.Add(actions);dialog.CancelButton=close;Ui.ApplyTheme(dialog);dialog.ShowDialog(this);}}
